CREATE TABLE IF NOT EXISTS leads (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID REFERENCES companies(id), contact_id UUID REFERENCES contacts(id), source TEXT, title TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'new', estimated_value NUMERIC(12,2), assigned_user_id UUID REFERENCES users(id), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS opportunities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES companies(id), contact_id UUID REFERENCES contacts(id), lead_id UUID REFERENCES leads(id), name TEXT NOT NULL, stage TEXT NOT NULL DEFAULT 'qualification', status TEXT NOT NULL DEFAULT 'open', deal_value NUMERIC(12,2) NOT NULL DEFAULT 0, probability INT NOT NULL DEFAULT 0 CHECK (probability >= 0 AND probability <= 100), expected_close_date DATE, owner_user_id UUID REFERENCES users(id), won_at TIMESTAMPTZ, lost_at TIMESTAMPTZ, lost_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quotes (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), company_id UUID NOT NULL REFERENCES companies(id), opportunity_id UUID REFERENCES opportunities(id), quote_number TEXT NOT NULL UNIQUE, status TEXT NOT NULL DEFAULT 'draft', subtotal NUMERIC(12,2) NOT NULL DEFAULT 0, tax_total NUMERIC(12,2) NOT NULL DEFAULT 0, total NUMERIC(12,2) NOT NULL DEFAULT 0, valid_until DATE, created_by_user_id UUID REFERENCES users(id), accepted_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS quote_lines (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), quote_id UUID NOT NULL REFERENCES quotes(id) ON DELETE CASCADE, description TEXT NOT NULL, quantity NUMERIC(12,2) NOT NULL DEFAULT 1, unit_price NUMERIC(12,2) NOT NULL DEFAULT 0, tax_rate NUMERIC(5,2) NOT NULL DEFAULT 0, line_total NUMERIC(12,2) NOT NULL DEFAULT 0, sort_order INT NOT NULL DEFAULT 0);
